"""Schemas generated by drf-spectacular (see tests/fixtures/drf) work end to end.

Tests read only the committed YAML; they never import Django.
"""

from __future__ import annotations

import json
from contextlib import asynccontextmanager
from pathlib import Path
from typing import TYPE_CHECKING, Any

import httpx2
import pytest
import yaml
from fastmcp import Client

from openapi_mcp_gateway.config.loader import load_gateway_config
from openapi_mcp_gateway.config.validator import validate_config
from openapi_mcp_gateway.mcp.gateway import build_server
from openapi_mcp_gateway.pipeline import prepare_all

if TYPE_CHECKING:
    from collections.abc import AsyncIterator

DRF = Path(__file__).parents[1] / "fixtures" / "drf"
ENV = {"DRF_AUTHORIZATION": "Token secret-token"}

pytestmark = pytest.mark.parametrize("schema", ["openapi-3.0.yaml", "openapi-3.1.yaml"])


def _prepare(tmp_path: Path, schema: str, mode: str) -> Any:
    backend = yaml.safe_load((DRF / "backend.yaml").read_text(encoding="utf-8"))
    backend["schema"] = str(DRF / schema)
    backend["exposure"]["mode"] = mode
    gateway = tmp_path / "gateway.yaml"
    gateway.write_text(yaml.safe_dump({"version": 1}), encoding="utf-8")
    backend_dir = tmp_path / "backends" / "drf"
    backend_dir.mkdir(parents=True, exist_ok=True)
    (backend_dir / "backend.yaml").write_text(yaml.safe_dump(backend), encoding="utf-8")
    cfg = load_gateway_config(gateway)
    validate_config(cfg)
    return cfg, prepare_all(cfg)


@asynccontextmanager
async def running(
    tmp_path: Path, schema: str, mode: str = "all"
) -> AsyncIterator[tuple[Client[Any], list[httpx2.Request]]]:
    cfg, prepared = _prepare(tmp_path, schema, mode)
    seen: list[httpx2.Request] = []

    def handler(request: httpx2.Request) -> httpx2.Response:
        seen.append(request)
        return httpx2.Response(200, json={"ok": True})

    server = build_server(
        cfg, prepared, ENV, inner_transports={"drf": httpx2.MockTransport(handler)}
    )
    async with Client(server) as client:
        yield client, seen


async def _tools(tmp_path: Path, schema: str, mode: str = "all") -> dict[str, Any]:
    async with running(tmp_path, schema, mode) as (client, _):
        return {t.name: t for t in await client.list_tools()}


class TestDrf:
    def test_validates(self, tmp_path: Path, schema: str) -> None:
        _, prepared = _prepare(tmp_path, schema, "all")
        expected = "3.0.3" if "3.0" in schema else "3.1.0"
        assert prepared[0].openapi_version == expected
        assert not prepared[0].warnings

    def test_read_only_tools(self, tmp_path: Path, schema: str) -> None:
        _, prepared = _prepare(tmp_path, schema, "read_only")
        names = sorted(prepared[0].tool_names.values())
        assert names == [
            "drf_health_retrieve",
            "drf_orders_list",
            "drf_orders_retrieve",
            "drf_reports_list",
        ]

    async def test_all_mode_exposes_every_operation(self, tmp_path: Path, schema: str) -> None:
        tools = await _tools(tmp_path, schema)
        assert len(tools) == 8
        assert {"drf_orders_create", "drf_orders_partial_update", "drf_orders_destroy"} <= set(
            tools
        )

    async def test_pagination_params_exposed(self, tmp_path: Path, schema: str) -> None:
        tools = await _tools(tmp_path, schema, "read_only")
        properties = tools["drf_orders_list"].input_schema["properties"]
        assert {"page", "page_size"} <= set(properties)

    async def test_query_filter_enum_and_forwarding(self, tmp_path: Path, schema: str) -> None:
        async with running(tmp_path, schema, "read_only") as (client, seen):
            tools = {t.name: t for t in await client.list_tools()}
            status = tools["drf_orders_list"].input_schema["properties"]["status"]
            await client.call_tool("drf_orders_list", {"status": "active", "page": 2})
        assert set(status["enum"]) == {"pending", "active", "closed"}
        assert dict(seen[0].url.params) == {"status": "active", "page": "2"}

    async def test_path_param_required(self, tmp_path: Path, schema: str) -> None:
        tools = await _tools(tmp_path, schema, "read_only")
        input_schema = tools["drf_orders_retrieve"].input_schema
        assert "id" in input_schema["required"]
        assert input_schema["properties"]["id"]["type"] == "integer"

    async def test_path_param_substituted(self, tmp_path: Path, schema: str) -> None:
        async with running(tmp_path, schema, "read_only") as (client, seen):
            await client.call_tool("drf_orders_retrieve", {"id": 42})
        assert seen[0].url.path == "/orders/42/"
        assert seen[0].method == "GET"

    async def test_enum_field_in_body_schema(self, tmp_path: Path, schema: str) -> None:
        tools = await _tools(tmp_path, schema)
        status = tools["drf_orders_create"].input_schema["properties"]["status"]
        assert status["enum"] == ["pending", "active", "closed"]

    async def test_read_only_property_still_advertised_as_required(
        self, tmp_path: Path, schema: str
    ) -> None:
        # FastMCP LIMITATION (pinned, see docs/architecture.md): drf-spectacular lists the
        # readOnly `id` in `required`; FastMCP keeps it required in the tool's input schema
        # even though the property is read-only. FastMCP does not validate arguments, so
        # calls without `id` still succeed. If FastMCP stops doing this, update this test.
        tools = await _tools(tmp_path, schema)
        assert "id" in tools["drf_orders_create"].input_schema["required"]
        async with running(tmp_path, schema) as (client, seen):
            await client.call_tool("drf_orders_create", {"customer": "Ada", "amount": "1"})
        assert json.loads(seen[0].content) == {"customer": "Ada", "amount": "1"}

    async def test_nullable_field_accepts_null(self, tmp_path: Path, schema: str) -> None:
        async with running(tmp_path, schema) as (client, seen):
            await client.call_tool(
                "drf_orders_create",
                {"customer": "Ada", "amount": "10.50", "closed_at": None},
            )
        body = json.loads(seen[0].content)
        assert body["closed_at"] is None
        assert body["customer"] == "Ada"

    async def test_nested_serializer_body_forwarded(self, tmp_path: Path, schema: str) -> None:
        contact = {"name": "Bob", "phone": None}
        async with running(tmp_path, schema) as (client, seen):
            await client.call_tool(
                "drf_orders_create",
                {"customer": "Ada", "amount": "10.50", "contact": contact},
            )
        assert seen[0].method == "POST"
        assert seen[0].url.path == "/orders/"
        assert json.loads(seen[0].content)["contact"] == contact

    async def test_security_metadata_does_not_add_tool_parameters(
        self, tmp_path: Path, schema: str
    ) -> None:
        tools = await _tools(tmp_path, schema)
        for tool in tools.values():
            properties = {key.lower() for key in tool.input_schema.get("properties", {})}
            assert "authorization" not in properties
            assert "tokenauth" not in properties

    async def test_configured_credential_sent(self, tmp_path: Path, schema: str) -> None:
        async with running(tmp_path, schema, "read_only") as (client, seen):
            await client.call_tool("drf_health_retrieve", {})
        assert seen[0].headers["authorization"] == "Token secret-token"
